(()=>{
 const disabled=()=>navigator.doNotTrack==='1'||navigator.globalPrivacyControl===true||localStorage.getItem('storylove-analytics-optout')==='1';
 let session;try{session=sessionStorage.getItem('storylove-session')||crypto.randomUUID();sessionStorage.setItem('storylove-session',session);}catch{session=crypto.randomUUID();}
 const test=new URL(location.href).searchParams.get('analytics_test')==='1';let queue=[],timer,inflight=false,page='character',view=crypto.randomUUID(),seen=new Set(),observer,currentPage=null;
 function track(name,properties={}){try{if(disabled())return;queue.push({id:crypto.randomUUID(),session_id:session,name,timestamp:Date.now(),properties:{page,page_view_id:view,test,...properties}});if(queue.length>100)queue.shift();if(queue.length>=10)flush();else if(!timer)timer=setTimeout(flush,3000);}catch{}}
 async function flush(){clearTimeout(timer);timer=null;if(disabled()){queue=[];return;}if(inflight||!queue.length)return;inflight=true;const batch=queue.splice(0,20);try{const r=await fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({events:batch}),keepalive:true,signal:AbortSignal.timeout(1800)});if(!r.ok&&r.status!==400&&r.status!==413&&r.status!==415)queue.unshift(...batch);}catch{queue.unshift(...batch);}finally{inflight=false;queue=queue.slice(-100);if(queue.length)timer=setTimeout(flush,10000);}}
 function elementFor(b){const d=b.dataset;let element,item_id='',placement=b.closest('#sidebar')?'sidebar':b.closest('.bottomnav')?'mobile_nav':b.closest('.mobile')?'mobile_header':b.closest('.footer')?'footer':b.closest('.characterhero')?'banner':b.closest('.featured')?'character_grid':b.closest('.plan')?'credit_pack':b.closest('.detail')?'detail':b.closest('.chat')?'chat':'content';if(d.title){element='title_card';item_id=d.title;}else if(d.chat){element='chat_cta';item_id=d.chat;}else if(d.page)element='nav_'+d.page;else if(d.feature!==undefined){element='banner_dot';item_id=d.feature;}else if(d.action)element='action_'+d.action;else if(d.refill){element='refill';item_id=d.refill;}else if(d.genre)element='genre_'+d.genre;else if(d.regenerate!==undefined)element='regenerate';else if(d.suggestion)element='suggestion';else if(d.step!==undefined)element='builder_step_'+d.step;else if(d.like){element='favorite';item_id=d.like;}else if(b.id==='collapse')element='sidebar_collapse';else if(b.type==='submit'&&b.closest('#sendForm'))element='send_message';else return null;return {element,item_id,placement,page,page_view_id:view};}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const info=elementFor(b);if(info)track('ui_click',info);},true);
 function beacon(){try{if(disabled()||!queue.length)return;const batch=queue.slice(0,20);if(navigator.sendBeacon('/api/events',new Blob([JSON.stringify({events:batch})],{type:'application/json'})))queue.splice(0,batch.length);}catch{}}
 function scan(){observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const entry of entries){const b=entry.target,info=elementFor(b);if(!info||!entry.isIntersecting||entry.intersectionRatio<.5)continue;const key=[view,info.placement,info.element,info.item_id].join('|');if(seen.has(key))continue;seen.add(key);track('element_impression',info);}},{threshold:.5});document.querySelectorAll('button').forEach(b=>{if(elementFor(b))observer.observe(b);});}
 function pageView(next){if(next!==currentPage){currentPage=next;page=next;view=crypto.randomUUID();seen=new Set();track('page_view',{page});}scan();}
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')beacon();});window.addEventListener('pagehide',()=>beacon());
 window.storyAnalytics={track,pageView,scan,flush,beacon,session,flow:()=>crypto.randomUUID(),optOut:()=>{localStorage.setItem('storylove-analytics-optout','1');queue=[];clearTimeout(timer);}};
})();
